#!/usr/bin/env python3
"""stable-diffusion.cpp on Vulkan for Immuch360 Desktop: the sources, the build and the archive of the sdcpp jobs.

The 360° panoramas are generated by sd-cli, the program of stable-diffusion.cpp (MIT) on ggml (MIT), run as a child
process (lot P2; phase23/design-final-2026-10-27.md, sections 4.5 and 7.5). Its binaries come from our CI only, never
from the releases of leejet, which are not signed: the jobs sdcpp-windows and sdcpp-linux of immuch360-desktop.yml build
them from the commits of sd_cpp.lock.json next to this script, with the Vulkan SDK of LunarG it names (the headers and
glslc of Ubuntu 22.04 are too old for the Vulkan backend of ggml), and upload the archive
Immuch360-AI-sdcpp-<id>-<system>.zip. Its name does not start with Immuch360-Desktop-, so no release of the app ever
attaches it; immuch360-desktop-release.yml signs the Windows one (with_sdcpp), and publish_ai_components.py --from-run
takes both into ai-components-3.

  sdcpp_build.py lock --system SYSTEM [--github-output]
      the id of the lock, the commits, the SDK of SYSTEM (windows-x64 or linux-x64) and the name of the artifact
  sdcpp_build.py sources --dir DIR
      stable-diffusion.cpp at the commit of the lock, and its ggml submodule only (no web frontend, no WebP, no WebM),
      checked against the commit of the lock
  sdcpp_build.py build --system SYSTEM --source DIR --build DIR
      cmake with the options of the lock, then the build; on Windows inside the environment of the newest Visual
      Studio with the C++ tools (vswhere, VsDevCmd), so that Ninja and cl are those of Visual Studio 2022
  sdcpp_build.py pack --system SYSTEM --source DIR --bin DIR --out DIR [--launcher FILE] [--crt-dir DIR]
                      [--system-dir DIR]
      the archive of the engine in DIR: sd-cli, the libraries of stable-diffusion.cpp and of ggml (every CPU variant
      and the Vulkan backend, which ggml loads from the folder of the program), on Windows the Visual C++ runtime DLLs
      they import (a clean Windows has none) and every import checked as windows_bundle.py does, on Linux the launcher
      immuch360-run and every library they need found in the archive or in the base of any distribution (libvulkan.so.1
      comes with the graphics driver); the licences of licenses/sdcpp in licenses/ (those of stable-diffusion.cpp and
      ggml compared with the sources built), and BUILD-INFO.txt. Sorted names, fixed dates: the same files give the
      same bytes.
  sdcpp_build.py help --output FILE [--fixture FILE]
      the output of sd-cli --help compared with mobile/test/fixtures/ai_immersive/sd_cli_help.txt, the text the
      arguments of mobile/lib/desktop/ai/gen/sdcpp_runner.dart are frozen by (the program's name and the version line
      apart): a new commit of stable-diffusion.cpp that renames an option fails here, not in a user's generation

Only the Python standard library is used. Exit codes: 0 good, 1 a check failed, 2 bad arguments or missing inputs.
"""
from __future__ import annotations

import argparse
import difflib
import hashlib
import json
import os
import pathlib
import re
import shutil
import struct
import subprocess
import sys
import tempfile
import zipfile

ROOT = pathlib.Path(__file__).resolve().parents[3]
LOCK = pathlib.Path(__file__).resolve().parent / 'sd_cpp.lock.json'
LICENCES = ROOT / 'licenses' / 'sdcpp'
FIXTURE = ROOT / 'mobile' / 'test' / 'fixtures' / 'ai_immersive' / 'sd_cli_help.txt'
SYSTEMS = ('windows-x64', 'linux-x64')
ARTIFACT_PREFIX = 'Immuch360-AI-sdcpp-'
# The files of a Windows build that make the engine: the program, the library of stable-diffusion.cpp, and those of
# ggml (ggml, ggml-base, ggml-vulkan and the CPU variants); sd-server and the build tools stay out
WINDOWS_FILES = re.compile(r'(?i)^(sd-cli\.exe|stable-diffusion\.dll|ggml[\w.-]*\.dll)$')
LINUX_PROGRAMS = ('sd-cli',)
LINUX_LIBRARIES = re.compile(r'^lib(stable-diffusion|ggml[\w.-]*)\.so(\.\d+)*$')
# What any Linux distribution of the desktop has (glibc 2.35 and the GCC runtime of Ubuntu 22.04, the base of the
# Linux packages), and the Vulkan loader, which comes with the graphics drivers
LINUX_SYSTEM = {'libc.so.6', 'libm.so.6', 'libstdc++.so.6', 'libgcc_s.so.1', 'libpthread.so.0', 'libdl.so.2',
                'librt.so.1', 'ld-linux-x86-64.so.2', 'libvulkan.so.1'}
LICENCE_SOURCES = {'stable-diffusion.cpp-LICENSE.txt': 'LICENSE', 'ggml-LICENSE.txt': 'ggml/LICENSE'}


class Failure(Exception):
    pass


def load_lock(path: pathlib.Path = LOCK) -> dict:
    lock = json.loads(path.read_text(encoding='utf-8'))
    for key in ('id', 'stableDiffusionCpp', 'ggml', 'vulkanSdk', 'cmake'):
        if key not in lock:
            raise Failure(f'{path.name}: no {key}')
    if not re.fullmatch(r'[0-9a-f]{7}-\d+', lock['id']):
        raise Failure(f'{path.name}: the id {lock["id"]!r} is not <short commit>-<build>')
    if not lock['stableDiffusionCpp']['commit'].startswith(lock['id'].split('-')[0]):
        raise Failure(f'{path.name}: the id {lock["id"]} does not start with the commit of stable-diffusion.cpp')
    for name in ('stableDiffusionCpp', 'ggml'):
        if not re.fullmatch(r'[0-9a-f]{40}', lock[name]['commit']):
            raise Failure(f'{path.name}: the commit of {name} is not a full commit')
    for system in SYSTEMS:
        sdk = lock['vulkanSdk'].get(system) or {}
        if not re.fullmatch(r'[0-9a-f]{64}', sdk.get('sha256', '')) or not sdk.get('url', '').startswith('https://'):
            raise Failure(f'{path.name}: the Vulkan SDK of {system} has no https address or SHA-256')
    return lock


def artifact_name(lock: dict, system: str) -> str:
    return f'{ARTIFACT_PREFIX}{lock["id"]}-{system}.zip'


def run(command: list, cwd: pathlib.Path | None = None):
    print('$ ' + ' '.join(str(part) for part in command), flush=True)
    subprocess.run([str(part) for part in command], cwd=cwd, check=True)


def output(command: list, cwd: pathlib.Path | None = None) -> str:
    return subprocess.run([str(part) for part in command], cwd=cwd, check=True, capture_output=True,
                          text=True).stdout.strip()


# --- lock ------------------------------------------------------------------------------------------------------------

def command_lock(args) -> int:
    lock = load_lock(args.lock)
    sdk = lock['vulkanSdk'][args.system]
    values = {
        'id': lock['id'],
        'artifact': artifact_name(lock, args.system),
        'commit': lock['stableDiffusionCpp']['commit'],
        'ggml_commit': lock['ggml']['commit'],
        'sdk_version': lock['vulkanSdk']['version'],
        'sdk_url': sdk['url'],
        'sdk_sha256': sdk['sha256'],
    }
    for key, value in values.items():
        print(f'{key}={value}')
    if args.github_output:
        with open(os.environ['GITHUB_OUTPUT'], 'a', encoding='utf-8') as stream:
            for key, value in values.items():
                stream.write(f'{key}={value}\n')
    return 0


# --- sources ---------------------------------------------------------------------------------------------------------

def fetch_commit(folder: pathlib.Path, repository: str, commit: str):
    folder.mkdir(parents=True, exist_ok=True)
    run(['git', 'init', '-q', folder])
    run(['git', '-C', folder, 'fetch', '-q', '--depth', '1', repository, commit])
    run(['git', '-C', folder, 'checkout', '-q', '--detach', 'FETCH_HEAD'])
    found = output(['git', '-C', folder, 'rev-parse', 'HEAD'])
    if found != commit:
        raise Failure(f'{repository}: {found} checked out, the lock says {commit}')


def command_sources(args) -> int:
    lock = load_lock(args.lock)
    source = args.dir
    if source.exists():
        shutil.rmtree(source)
    fetch_commit(source, lock['stableDiffusionCpp']['repository'], lock['stableDiffusionCpp']['commit'])
    tree = output(['git', '-C', source, 'ls-tree', 'HEAD', 'ggml']).split()
    if len(tree) < 3 or tree[1] != 'commit' or tree[2] != lock['ggml']['commit']:
        raise Failure(f'stable-diffusion.cpp {lock["stableDiffusionCpp"]["commit"]} has ggml at '
                      f'{tree[2] if len(tree) > 2 else "?"}, the lock says {lock["ggml"]["commit"]}')
    fetch_commit(source / 'ggml', lock['ggml']['repository'], lock['ggml']['commit'])
    print(f'stable-diffusion.cpp {lock["stableDiffusionCpp"]["commit"]}, ggml {lock["ggml"]["commit"]} in {source}')
    return 0


# --- build -----------------------------------------------------------------------------------------------------------

def visual_studio() -> pathlib.Path:
    vswhere = pathlib.Path(os.environ.get('ProgramFiles(x86)', r'C:\Program Files (x86)'),
                           'Microsoft Visual Studio', 'Installer', 'vswhere.exe')
    if not vswhere.exists():
        raise Failure('no vswhere.exe: no Visual Studio on this computer')
    found = output([vswhere, '-latest', '-products', '*', '-requires',
                    'Microsoft.VisualStudio.Component.VC.Tools.x86.x64', '-property', 'installationPath'])
    if not found:
        raise Failure('no Visual Studio with the C++ tools')
    return pathlib.Path(found)


def batch_quote(part: str) -> str:
    return f'"{part}"' if re.search(r'[\s&|<>^()]', part) else part


def command_build(args) -> int:
    lock = load_lock(args.lock)
    options = [*lock['cmake']['common'], *lock['cmake'][args.system]]
    configure = ['cmake', '-S', str(args.source), '-B', str(args.build), *options]
    # Four jobs, the processors of the hosted runners: more is the out of memory killer on the Vulkan backend
    build = ['cmake', '--build', str(args.build), '--config', 'Release', '--parallel', '4']
    if args.system == 'linux-x64':
        run(configure)
        run(build)
        return 0
    studio = visual_studio()
    script = pathlib.Path(tempfile.mkdtemp(prefix='sdcpp-')) / 'build.bat'
    script.write_text('\r\n'.join([
        '@echo off',
        f'call "{studio}\\Common7\\Tools\\VsDevCmd.bat" -arch=x64 -host_arch=x64 -no_logo || exit /b 1',
        'where cl ninja cmake',
        ' '.join(batch_quote(part) for part in configure) + ' || exit /b 1',
        ' '.join(batch_quote(part) for part in build) + ' || exit /b 1',
        '',
    ]), encoding='utf-8')
    print(f'Visual Studio: {studio}')
    run(['cmd.exe', '/d', '/c', str(script)])
    return 0


# --- pack ------------------------------------------------------------------------------------------------------------

def elf_needed(data: bytes) -> list:
    """The DT_NEEDED names of a 64 bit little endian ELF file"""
    if data[:4] != b'\x7fELF' or data[4] != 2 or data[5] != 1:
        raise Failure('not a 64 bit little endian ELF file')
    shoff, = struct.unpack_from('<Q', data, 0x28)
    shentsize, shnum = struct.unpack_from('<HH', data, 0x3A)
    sections = [struct.unpack_from('<IIQQQQIIQQ', data, shoff + index * shentsize) for index in range(shnum)]
    needed = []
    for _, kind, _, _, offset, size, link, _, _, entsize in sections:
        if kind != 6:  # SHT_DYNAMIC
            continue
        strings = sections[link]
        for at in range(offset, offset + size, entsize or 16):
            tag, value = struct.unpack_from('<qQ', data, at)
            if tag == 0:
                break
            if tag == 1:  # DT_NEEDED
                start = strings[4] + value
                needed.append(data[start:data.index(b'\0', start)].decode())
    return needed


def linux_files(bin_dir: pathlib.Path, launcher: pathlib.Path | None) -> tuple:
    """The files of the Linux engine by name, and the problems: the programs, the backends of ggml (loaded from the
    folder), and every library they need under the name they ask for"""
    files, problems = {}, []
    for name in LINUX_PROGRAMS:
        if not (bin_dir / name).is_file():
            raise Failure(f'no {name} in {bin_dir}')
        files[name] = (bin_dir / name).read_bytes()
    if launcher is not None:
        files['immuch360-run'] = launcher.read_bytes()
    for path in sorted(bin_dir.iterdir()):
        # The backends ggml loads by their names (libggml-vulkan.so, libggml-cpu-<variant>.so), never asked for by NEEDED
        if re.fullmatch(r'libggml-(vulkan|cpu[\w-]*)\.so', path.name) and path.is_file():
            files[path.name] = path.resolve().read_bytes()
    pending = list(files)
    while pending:
        name = pending.pop()
        for needed in elf_needed(files[name]):
            if needed in files or needed in LINUX_SYSTEM:
                continue
            if LINUX_LIBRARIES.match(needed) and (bin_dir / needed).exists():
                files[needed] = (bin_dir / needed).resolve().read_bytes()
                pending.append(needed)
            else:
                problems.append(f'{name} needs {needed}, found neither in the build nor in the base of a distribution')
    return files, problems


def windows_files(bin_dir: pathlib.Path, crt_dir: pathlib.Path | None, system_dir: pathlib.Path | None) -> tuple:
    """The files of the Windows engine by name, with the Visual C++ runtime DLLs they import, and the problems"""
    sys.path.insert(0, str(ROOT / '.github' / 'desktop'))
    import windows_bundle  # noqa: E402 (the import checks of the Windows ZIP of the app)

    crt_dir = crt_dir or windows_bundle.find_crt_dir('x64')
    if crt_dir is None or not crt_dir.is_dir():
        raise Failure('no Visual C++ redistributable folder: give --crt-dir')
    system_dir = system_dir or pathlib.Path(os.environ.get('SystemRoot', r'C:\Windows'), 'System32')
    with tempfile.TemporaryDirectory(prefix='sdcpp-') as temporary:
        folder = pathlib.Path(temporary)
        for path in sorted(bin_dir.iterdir()):
            if path.is_file() and WINDOWS_FILES.match(path.name):
                shutil.copy2(path, folder / path.name)
        if not (folder / 'sd-cli.exe').is_file() or not (folder / 'ggml-vulkan.dll').is_file():
            raise Failure(f'no sd-cli.exe or no ggml-vulkan.dll in {bin_dir}')
        crt = {path.name.lower(): path for path in crt_dir.glob('*.dll')}
        system = {name.lower() for name in os.listdir(system_dir)}
        copied = []
        problems = windows_bundle.check(folder, 'x64', crt, system, copied)
        for name in copied:
            print(f'Visual C++ runtime: {name}')
        return {path.name: path.read_bytes() for path in sorted(folder.iterdir())}, problems


def write_archive(target: pathlib.Path, files: dict, programs: set):
    target.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(target, 'w', zipfile.ZIP_DEFLATED, compresslevel=9) as bundle:
        for name in sorted(files):
            info = zipfile.ZipInfo(name, date_time=(1980, 1, 1, 0, 0, 0))
            info.create_system = 3
            info.external_attr = (0o100755 if name in programs else 0o100644) << 16
            info.compress_type = zipfile.ZIP_DEFLATED
            bundle.writestr(info, files[name], compresslevel=9)


def command_pack(args) -> int:
    lock = load_lock(args.lock)
    problems = []
    for name, source in LICENCE_SOURCES.items():
        ours = (LICENCES / name).read_bytes().replace(b'\r\n', b'\n').strip()
        theirs = (args.source / source).read_bytes().replace(b'\r\n', b'\n').strip()
        if ours != theirs:
            problems.append(f'licenses/sdcpp/{name} differs from {source} of the sources built: copy it again')
    if args.system == 'windows-x64':
        files, found = windows_files(args.bin, args.crt_dir, args.system_dir)
        programs = {'sd-cli.exe'}
    else:
        files, found = linux_files(args.bin, args.launcher)
        programs = {'sd-cli', 'immuch360-run'} & set(files)
    problems += found
    for path in sorted(LICENCES.iterdir()):
        if path.is_file():
            files[f'licenses/{path.name}'] = path.read_bytes()
    run_url = ''
    if os.environ.get('GITHUB_RUN_ID'):
        run_url = (f'{os.environ.get("GITHUB_SERVER_URL", "https://github.com")}/{os.environ.get("GITHUB_REPOSITORY")}'
                   f'/actions/runs/{os.environ["GITHUB_RUN_ID"]}')
    files['BUILD-INFO.txt'] = '\n'.join([
        f'stable-diffusion.cpp on Vulkan for Immuch360 Desktop, {args.system}, lock {lock["id"]}',
        f'stable-diffusion.cpp {lock["stableDiffusionCpp"]["repository"]} {lock["stableDiffusionCpp"]["commit"]}',
        f'ggml {lock["ggml"]["repository"]} {lock["ggml"]["commit"]}',
        f'Vulkan SDK of LunarG {lock["vulkanSdk"]["version"]}',
        'CMake options: ' + ' '.join([*lock['cmake']['common'], *lock['cmake'][args.system]]),
        *([f'Built by {run_url}'] if run_url else []),
        'Licences: licenses/ (stable-diffusion.cpp and ggml under the MIT licence, the code built into them in '
        'licenses/THIRD-PARTY.md)',
        '',
    ]).encode()
    if problems:
        for problem in problems:
            print(f'::error::{problem}')
        return 1
    target = args.out / artifact_name(lock, args.system)
    write_archive(target, files, programs)
    for name in sorted(files):
        print(f'{len(files[name]):>10}  {hashlib.sha256(files[name]).hexdigest()}  {name}'
              + ('  (program)' if name in programs else ''))
    digest = hashlib.sha256(target.read_bytes()).hexdigest()
    print(f'{target.name}: {target.stat().st_size} bytes, SHA-256 {digest}')
    if os.environ.get('GITHUB_OUTPUT'):
        with open(os.environ['GITHUB_OUTPUT'], 'a', encoding='utf-8') as stream:
            stream.write(f'archive={target}\n')
    return 0


# --- help ------------------------------------------------------------------------------------------------------------

def normalized_help(text: str) -> list:
    """The lines of sd-cli --help without the version line, with the program named sd-cli on every system"""
    lines = text.replace('\r\n', '\n').split('\n')
    while lines and not lines[-1].strip():
        lines.pop()
    if lines and lines[0].startswith('stable-diffusion.cpp version'):
        lines = lines[1:]
    return [re.sub(r'^Usage: \S*sd-cli(\.exe)?', 'Usage: sd-cli', line) for line in lines]


def command_help(args) -> int:
    lock = load_lock(args.lock)
    text = args.output.read_text(encoding='utf-8', errors='replace')
    first = text.replace('\r\n', '\n').split('\n', 1)[0]
    short = lock['stableDiffusionCpp']['commit'][:7]
    if f'commit {short}' not in first:
        print(f'::error::sd-cli --help says {first!r}, the lock says commit {short}')
        return 1
    built, frozen = normalized_help(text), normalized_help(args.fixture.read_text(encoding='utf-8'))
    if built != frozen:
        print('::error::sd-cli --help differs from the fixture the arguments of the runner are frozen by:')
        sys.stdout.writelines(line + '\n' for line in difflib.unified_diff(frozen, built, 'fixture', 'built', lineterm=''))
        return 1
    print(f'sd-cli --help: {len(built)} lines, the same as {args.fixture.name}; {first}')
    return 0


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument('--lock', type=pathlib.Path, default=LOCK)
    commands = parser.add_subparsers(dest='command', required=True)
    lock = commands.add_parser('lock')
    lock.add_argument('--system', choices=SYSTEMS, required=True)
    lock.add_argument('--github-output', action='store_true')
    sources = commands.add_parser('sources')
    sources.add_argument('--dir', type=pathlib.Path, required=True)
    build = commands.add_parser('build')
    build.add_argument('--system', choices=SYSTEMS, required=True)
    build.add_argument('--source', type=pathlib.Path, required=True)
    build.add_argument('--build', type=pathlib.Path, required=True)
    pack = commands.add_parser('pack')
    pack.add_argument('--system', choices=SYSTEMS, required=True)
    pack.add_argument('--source', type=pathlib.Path, required=True)
    pack.add_argument('--bin', type=pathlib.Path, required=True)
    pack.add_argument('--out', type=pathlib.Path, required=True)
    pack.add_argument('--launcher', type=pathlib.Path)
    pack.add_argument('--crt-dir', type=pathlib.Path)
    pack.add_argument('--system-dir', type=pathlib.Path)
    check = commands.add_parser('help')
    check.add_argument('--output', type=pathlib.Path, required=True)
    check.add_argument('--fixture', type=pathlib.Path, default=FIXTURE)
    args = parser.parse_args(argv)
    if args.command == 'pack' and args.system == 'linux-x64' and args.launcher is None:
        parser.error('the Linux engine needs --launcher (immuch360-run)')
    try:
        return {'lock': command_lock, 'sources': command_sources, 'build': command_build, 'pack': command_pack,
                'help': command_help}[args.command](args)
    except (Failure, OSError, subprocess.CalledProcessError, json.JSONDecodeError) as error:
        print(f'::error::{error}')
        return 1 if isinstance(error, (Failure, subprocess.CalledProcessError)) else 2


if __name__ == '__main__':
    sys.exit(main())
